380				return group, artifact, ""
381			}
382		case "pypi":
383			name = strings.ToLower(strings.ReplaceAll(n, "_", "-"))
384		case "golang":
385			if i := strings.LastIndex(n, "/"); i >= 0 {
386				return n[:i], n[i+1:], ""
387			}
388		case "npm":
389			if strings.HasPrefix(n, "@") {
390				if scope, pkg, ok := strings.Cut(n, "/"); ok {
391					return scope, pkg, ""
392				}
393			}
394		case "cocoapods":
395			if pkg, path, ok := strings.Cut(n, "/"); ok {
396				return "", pkg, path
397			}
398		}
399		return "", name, ""
400	}
